function validate([nums1, nums2, nums3, nums4]) {
  const LIMIT = 268435456;
  const arrays = [nums1, nums2, nums3, nums4];
  if (arrays.some(list => !Array.isArray(list))) return 'Each of the four inputs must be an array.';
  const n = nums1.length;
  if (n < 1 || n > 200) return 'Each array needs 1 to 200 values.';
  if (arrays.some(list => list.length !== n)) return 'All four arrays must have the same length.';
  if (arrays.some(list => list.some(v => !Number.isInteger(v) || v < -LIMIT || v > LIMIT))) return 'Each value is a whole number between -2^28 and 2^28.';
  return null;
}

