      const sum = a + b;
      pairCounts.set(sum, (pairCounts.get(sum) ?? 0) + 1);
    }
  }

  let count = 0;
  for (const c of nums3) {
    for (const d of nums4) {
      const need = -(c + d);
      count += pairCounts.get(need) ?? 0;
