function fourSumCount(nums1, nums2, nums3, nums4) {
  // Sorted pair sums of both halves, matched with two pointers (no hashing).
  const halves = (xs, ys) => xs.flatMap(x => ys.map(y => x + y)).sort((p, q) => p - q);
  const front = halves(nums1, nums2);
  const back = halves(nums3, nums4);
  let total = 0;
  let i = 0;
  let j = back.length - 1;
  while (i < front.length && j >= 0) {
    const s = front[i] + back[j];
    if (s < 0) i++;
    else if (s > 0) j--;
    else {
      let runFront = 0;
      let runBack = 0;
      const x = front[i], y = back[j];
      while (i < front.length && front[i] === x) { i++; runFront++; }
      while (j >= 0 && back[j] === y) { j--; runBack++; }
      total += runFront * runBack;
    }
  }
  return total;
}

