function generate(rand, size) {
  const LIMIT = 268435456;
  if (size === 'large') {
    const scale = rand() < 0.5 ? 1 : 4194304;
    const spread = 1 + Math.floor(rand() * 40);
    const make = () => Array.from({ length: 200 }, () => (Math.floor(rand() * (2 * spread + 1)) - spread) * scale);
    return [make(), make(), make(), make()];
  }
  const n = 1 + Math.floor(rand() * 6);
  const spread = 1 + Math.floor(rand() * 4);
  const value = () => {
    const roll = rand();
    if (roll < 0.08) return LIMIT;
    if (roll < 0.16) return -LIMIT;
    return Math.floor(rand() * (2 * spread + 1)) - spread;
  };
  const make = () => Array.from({ length: n }, value);
  return [make(), make(), make(), make()];
}
